# create_press_release_hwpx.ps1
# 보도자료양식.hwpx를 클론하여 새 기사 내용으로 교체

Add-Type -Assembly System.IO.Compression
Add-Type -Assembly System.IO.Compression.FileSystem

$srcHwpx  = "C:\Users\user\Downloads\work11\보도자료양식.hwpx"
$outHwpx  = "C:\Users\user\Downloads\work11\골목엔_나홀로_사장_방안엔_쉬는_청년_고용단절_보도자료.hwpx"
$tempDir  = "C:\Users\user\Downloads\work11\_hwpx_temp"

# 임시 디렉토리 초기화
if (Test-Path $tempDir) { Remove-Item $tempDir -Recurse -Force }
New-Item -ItemType Directory -Path $tempDir | Out-Null

# 1) 원본 HWPX 압축 해제
[System.IO.Compression.ZipFile]::ExtractToDirectory($srcHwpx, $tempDir)
Write-Host "원본 HWPX 추출 완료"

