pan="1" rowSpan="1"/><hp:cellSz width="48180" height="14277"/><hp:cellMargin left="141" right="141" top="141" bottom="141"/></hp:tc></hp:tr></hp:tbl><hp:t/></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="14960" vertsize="14559" textheight="14559" baseline="12375" spacing="780" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="33" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="49"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="30299" vertsize="800" textheight="800" baseline="680" spacing="480" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="49" styleIDRef="4" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="52"><hp:t>통계청</hp:t></hp:run><hp:run charPrIDRef="51"><hp:t>이 2026년 8월 경제활동인구조사 근로형태별 부가조사 결과를 발표했다. 조사 결과에 따르면 자영업자의 고용 기피 현상이 심화되고 청년층의 취업 단념이 가속화되면서 노동시장의 고용 사다리가 무너지고 있다는 경고등이 켜졌다.</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="31579" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="2490368"/><hp:lineseg textpos="37" vertpos="33979" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="1441792"/><hp:lineseg textpos="76" vertpos="36379" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="1441792"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="38" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="38779" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="50" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="55"><hp:t>&#x25a0; 1. &#x2018;알바 쓸 돈도 없다&#x2019;&#x2026; 고용 포기한 &#x2018;나홀로 사장님&#x2019;</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="41179" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="37" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="43579" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="47" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="54"><hp:t>2026년 8월 기준 비임금근로자는 659만 2천 명으로, 이 중 고용원 없는 자영업자(&#x2018;나홀로 사장&#x2019;)가 전체 자영업자의 64.8%인 427만 7천 명에 달한다. 고용원 있는 자영업자는 232만 7천 명으로 2년 전보다 약 7만 명 감소했다. 나홀로 사장의 비중은 역대 최고 수준으로, 직원을 고용할 여력이 없거나 고용을 의도적으로 기피하는 추세가 뚜렷하게 나타나고 있다.</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="45979" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/><hp:lineseg textpos="37" vertpos="48379" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="76" vertpos="50779" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="112" vertpos="53179" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="47" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="54"><hp:t>나홀로 사장의 주당 평균 취업시간은 44.2시간으로, 임금근로자(39.4시간)보다 길지만 가장 큰 경영 애로로는 &#x2018;매출 부진&#x2019;(39.5%)을 꼽았다. 경기 침체가 길어지면서 고용 여력이 소진되고 있는 것이다. 이처럼 소상공인의 고용 포기가 고착화되면 사회 초년생이 첫 경험을 쌓을 아르바이트 자리와 초기 일자리가 사라지는 연쇄 효과로 이어진다.</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="55579" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/><hp:lineseg textpos="37" vertpos="57979" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="76" vertpos="60379" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="112" vertpos="62779" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="38" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="65179" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="50" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="55"><hp:t>&#x25a0; 2. &#x2018;갈 만한 곳 없다&#x2019;&#x2026; 취업 희망률 19.9%, 20%선 붕괴</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="67579" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="37" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="69979" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="47" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="54"><hp:t>비경제활동인구는 1,629만 7천 명으로, 이 중 취업을 희망하는 비율은 19.9%로 나타났다. 이는 사상 처음으로 20% 선이 붕괴된 수치로, 구직 의욕 자체가 꺼지고 있음을 보여준다. 특히 취업을 원하지 않는 청년층(15~29세) 비중이 35.2%에 달하며, 이들이 취업을 단념한 가장 큰 이유는 &#x2018;원하는 일자리가 없어서&#x2019;(복수응답)였다.</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="72379" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/><hp:lineseg textpos="37" vertpos="74779" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="76" vertpos="77179" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="112" vertpos="79579" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="47" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="54"><hp:t>취업 준비를 하지 않는 청년들 사이에서는 &#x2018;그냥 쉬고 있다&#x2019;는 응답과 함께 &#x2018;학원·취업 준비를 하겠다&#x2019;는 답변이 혼재하는데, 이는 적극적 구직이 아닌 &#x2018;취업 도피&#x2019; 양상으로 해석된다. 비경활 청년이 1년 내 취업을 희망하는 비율도 2년 연속 하락세를 보이고 있어, 청년층의 노동시장 이탈이 구조적으로 고착화될 우려가 크다.</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="82379" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/><hp:lineseg textpos="37" vertpos="84779" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="76" vertpos="0" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="112" vertpos="2400" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/></hp:linesegarray></hp:p><hp:p id="2147483648" paraPrIDRef="42" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="4800" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="50" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="55"><hp:t>&#x25a0; 3. 첫 일자리 디딤돌 실종&#x2026; 노동시장 이중구조와 양극화의 덫</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="7200" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="37" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="9600" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="47" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="54"><hp:t>임금근로자 2,252만 6천 명 중 비정규직은 892만 3천 명(39.6%)이다. 청년 비정규직 근로자는 148만 2천 명으로 전년 대비 소폭 증가했으며, 이들의 월평균 임금은 211만 원으로 정규직(405만 원)의 절반 수준에도 못 미친다. 임금 격차가 194만 원에 달하는 이 구조에서 청년들은 비정규직을 &#x2018;징검다리&#x2019;가 아닌 &#x2018;막다른 길&#x2019;로 인식하게 된다.</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="12000" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/><hp:lineseg textpos="37" vertpos="14400" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="76" vertpos="16800" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="112" vertpos="19200" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="47" styleIDRef="5" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="54"><hp:t>나홀로 사장의 증가로 첫 직장·아르바이트 자리가 줄고, 청년이 비경제활동으로 이탈하며, 비정규직 처우는 개선되지 않는 삼중 악순환이 한국 고용 사다리를 무너뜨리고 있다. 전문가들은 소상공인 고용 지원, 청년 맞춤형 일자리 질 개선, 비정규직 처우 현실화 등 구조적 처방 없이는 현 추세가 더욱 심화될 것이라고 경고한다.</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="21600" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="393216"/><hp:lineseg textpos="37" vertpos="24000" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="76" vertpos="26400" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/><hp:lineseg textpos="112" vertpos="28800" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="1000" horzsize="47188" flags="1441792"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="34" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="31200" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="2147483648" paraPrIDRef="3" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"><hp:tbl id="1217921310" zOrder="4" numberingType="TABLE" textWrap="TOP_AND_BOTTOM" textFlow="BOTH_SIDES" lock="0" dropcapstyle="None" pageBreak="CELL" repeatHeader="1" rowCnt="4" colCnt="3" cellSpacing="0" borderFillIDRef="2" noAdjust="0"><hp:sz width="48114" widthRelTo="ABSOLUTE" height="9000" heightRelTo="ABSOLUTE" protect="0"/><hp:pos treatAsChar="1" affectLSpacing="0" flowWithText="1" allowOverlap="0" holdAnchorAndSO="0" vertRelTo="PARA" horzRelTo="PARA" vertAlign="TOP" horzAlign="LEFT" vertOffset="0" horzOffset="0"/><hp:outMargin left="141" right="141" top="141" bottom="141"/><hp:inMargin left="140" right="140" top="140" bottom="140"/><hp:tr><hp:tc name="" header="1" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="15"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="58"><hp:t>구분</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpo