="0" protect="0" editable="0" dirty="0" borderFillIDRef="15"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>나홀로 사장</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="13028" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="0" rowAddr="1"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="10000" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc><hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="15"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>자영업자 659만 2천 명 중 64.8%(427만 7천 명), 주당 44.2시간, 매출 부진 애로 39.5%</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="13988" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="1" rowAddr="1"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="20000" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc><hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="16"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>고용 포기 고착화&#x2192;청년 첫 일자리&#xb7;알바 자리 실종</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="20252" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="2" rowAddr="1"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="18114" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc></hp:tr><hp:tr><hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="15"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>청년 취업 단념</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="13028" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="0" rowAddr="2"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="10000" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc><hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="15"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>비경활인구 1,629만 7천 명, 취업 희망률 19.9%&#xb7;청년 35.2% &#x2018;일자리 없어&#x2019;</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="13988" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="1" rowAddr="2"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="20000" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc><hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="16"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>취업 포기 증가&#x2192;노동시장 이탈 구조화</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="20252" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="2" rowAddr="2"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="18114" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc></hp:tr><hp:tr><hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="15"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>임금 양극화</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="13028" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="0" rowAddr="3"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="10000" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc><hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="15"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>정규직 월 405만 원 vs 비정규직 211만 원, 청년 비정규직 148만 2천 명</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="13988" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="1" rowAddr="3"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="20000" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc><hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="16"><hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="CENTER" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0"><hp:p id="2147483648" paraPrIDRef="17" styleIDRef="9" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="51"><hp:t>비정규직=막다른 길 인식&#x2192;노동시장 이중구조 심화</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="0" vertsize="1100" textheight="1100" baseline="935" spacing="660" horzpos="0" horzsize="20252" flags="393216"/></hp:linesegarray></hp:p></hp:subList><hp:cellAddr colAddr="2" rowAddr="3"/><hp:cellSpan colSpan="1" rowSpan="1"/><hp:cellSz width="18114" height="2333"/><hp:cellMargin left="400" right="400" top="200" bottom="200"/></hp:tc></hp:tr></hp:tbl><hp:t/></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="33600" vertsize="9282" textheight="9282" baseline="7890" spacing="780" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="30" styleIDRef="7" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="44"><hp:t>&#x25cf; 본 보도자료는 2026년 8월 경제활동인구조사 근로형태별 부가조사(통계청) 결과에 기반하여 작성되었습니다.</hp:t></hp:run><hp:linesegarray><hp:lineseg textpos="0" vertpos="44282" vertsize="1300" textheight="1300" baseline="1105" spacing="780" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p><hp:p id="0" paraPrIDRef="3" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="11"/><hp:linesegarray><hp:lineseg textpos="0" vertpos="46362" vertsize="1500" textheight="1500" baseline="1275" spacing="900" horzpos="0" horzsize="48188" flags="393216"/></hp:linesegarray></hp:p></hs:sec>
'@

# 3) section0.xml 교체
$sec0Path = Join-Path $tempDir "Contents\section0.xml"
[System.IO.File]::WriteAllText($sec0Path, $newSection, [System.Text.Encoding]::UTF8)
Write-Host "section0.xml 교체 완료 (길이: $($newSection.Length))"

# 4) content.hpf 업데이트 (제목)
$hpfPath = Join-Path $tempDir "Contents\content.hpf"
if (Test-Path $hpfPath) {
    $hpfContent = [System.IO.File]::ReadAllText($hpfPath, [System.Text.Encoding]::UTF8)
    $hpfContent = $hpfContent -replace '<dc:title>[^<]*</dc:title>', '<dc:title>골목엔 나홀로 사장 방안엔 쉬는 청년 무너진 고용 사다리 보도자료</dc:title>'
    [System.IO.File]::WriteAllText($hpfPath, $hpfContent, [System.Text.Encoding]::UTF8)
    Write-Host "content.hpf 업데이트 완료"
}

# 5) PrvText.txt 업데이트
$prvTextPath = Join-Path $tempDir "Preview\PrvText.txt"
if (Test-Path $prvTextPath) {
    $prvText = "골목엔 '나홀로 사장', 방 안엔 '쉬는 청년'… 무너진 고용 사다리`n`n보도자료 | 2026. 11. 19.(목) 배포`n`n통계청 고용통계과"
    [System.IO.File]::WriteAllText($prvTextPath, $prvText, [System.Text.Encoding]::UTF8)
    Write-Host "PrvText.txt 업데이트 완료"
}

# 6) 출력 HWPX 생성 (mimetype 비압축 필수)
if (Test-Path $outHwpx) { Remove-Item $outHwpx -Force }

$outStream = [System.IO.File]::Create($outHwpx)
$archive = New-Object System.IO.Compression.ZipArchive($outStream, [System.IO.Compression.ZipArchiveMode]::Create, $true)

# mimetype 반드시 첫 번째, 비압축
$mimeEntry = $archive.CreateEntry("mimetype", [System.IO.Compression.CompressionLevel]::NoCompression)
$mimeWriter = New-Object System.IO.StreamWriter($mimeEntry.Open(), [System.Text.Encoding]::ASCII)
$mimeWriter.Write("application/haansofthwp")
$mimeWriter.Close()
Write-Host "mimetype 작성 완료"

# 나머지 파일들 추가
function Add-FileToZip {
    param($archive, $filePath, $entryName)
    $entry = $archive.CreateEntry($entryName, [System.IO.Compression.CompressionLevel]::Optimal)
    $entryStream = $entry.Open()
    $fileBytes = [System.IO.File]::ReadAllBytes($filePath)
    $entryStream.Write($fileBytes, 0, $fileBytes.Length)
    $entryStream.Close()
}

# 순서대로 파일 추가
$fileMappings = @(
    @{file="version.xml"; entry="version.xml"},
    @{file="Contents\header.xml"; entry="Contents/header.xml"},
    @{file="BinData\image1.jpg"; entry="BinData/image1.jpg"},
    @{file="BinData\image2.jpg"; entry="BinData/image2.jpg"},
    @{file="Contents\section0.xml"; entry="Contents/section0.xml"},
    @{file="Preview\PrvText.txt"; entry="Preview/PrvText.txt"},
    @{file="Scripts\headerScripts.js"; entry="Scripts/headerScripts.js"},
    @{file="Scripts\sourceScripts.js"; entry="Scripts/sourceScripts.js"},
    @{file="settings.xml"; entry="settings.xml"},
    @{file="Preview\PrvImage.png"; entry="Preview/PrvImage.png"},
    @{file="META-INF\container.rdf"; entry="META-INF/container.rdf"},
    @{file="Contents\content.hpf"; entry="Contents/content.hpf"},
    @{file="META-INF\container.xml"; entry="META-INF/container.xml"},
    @{file="META-INF\manifest.xml"; entry="META-INF/manifest.xml"}
)

foreach ($mapping in $fileMappings) {
    $fullPath = Join-Path $tempDir $mapping.file
    if (Test-Path $fullPath) {
        Add-FileToZip -archive $archive -filePath $fullPath -entryName $mapping.entry
        Write-Host "추가: $($mapping.entry)"
    } else {
        Write-Host "건너뜀 (파일 없음): $($mapping.file)"
    }
}

$archive.Dispose()
$outStream.Close()

Write-Host ""
$outSize = (Get-Item $outHwpx).Length
Write-Host "=== 완료 ==="
Write-Host "출력 파일: $outHwpx"
Write-Host "파일 크기: $outSize bytes"

# 임시 디렉토리 삭제
Remove-Item $tempDir -Recurse -Force
Write-Host "임시 디렉토리 삭제 완료"
